// ================== CONFIGURACIÓN DEL BOT ==================
const CONFIG = {
  crm_url: 'https://crm.aikonintelligence.com',
  tenant_id: 'f31be830-125f-4c61-9779-854607cac89c',
  webhook_secret: '',              // vacío: Agroapoya2 no tiene secreto en el CRM (si lo creas, ponlo aquí)
  ycloud_from: '+57XXXXXXXXXX',    // número de WhatsApp de Agroapoya2 registrado en YCloud
  espera_segundos: 8,              // buffer: espera antes de responder para juntar mensajes seguidos
  // Programa de embajadores (lo que no está en los términos: complétalo)
  grupo_embajadores_url: '',       // link de invitación al grupo de WhatsApp de embajadores
};
// ==========================================================
// El flujo de Entrada (enrutador) ya guardó el mensaje en el CRM, procesó audio/imagen/video
// y manda aquí: wa_id, contact_name, content, contact_id, conversation_id, message_id.
const b = $input.first().json.body ?? $input.first().json;
return [{ json: {
  config: CONFIG,
  wa_id: String(b.wa_id || '').replace(/\D/g, ''),
  contact_name: b.contact_name || '',
  content: b.content || '',
  contact_id: b.contact_id,
  conversation_id: b.conversation_id,
  message_id: b.message_id,
} }];

// ============================================================
// NODO: Catálogo compacto
//  - catalogo_compacto: texto corto para el prompt del Agente Ventas
//  - catalogo_json: lista estructurada para cotizar_pedido
//  - imagenes: { producto: url } si la hoja tiene una columna "Imagen" (para enviar fotos)
// ============================================================
const rows = $input.all().map(i => i.json);

const num = v => Number(String(v ?? '').replace(/[^\d]/g, '')) || 0;   // "$74.800" -> 74800
const pesos = n => '$' + Math.round(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const unidadCorta = u => (/^lib/i.test(u) ? 'lb' : (/^uni/i.test(u) ? 'und' : String(u || '').toLowerCase()));
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();

const items = [];
const imagenes = {};
for (const r of rows) {
  const nombre = String(r['Producto'] || '').trim();
  if (!nombre) continue;
  const img = String(r['Imagen'] || r['Imagen URL'] || r['Foto'] || '').trim();
  if (/^https?:\/\//.test(img) && !imagenes[norm(nombre)]) imagenes[norm(nombre)] = img;
  const pres = String(r['Presentación / Cantidad'] || '').match(/([\d.,]+)\s*([A-Za-zÁÉÍÓÚáéíóú]+)/) || [];
  const cantidad = Number(String(pres[1] || '').replace(',', '.'));
  const precio = num(r['Precio Total ($)']);
  if (!cantidad || !precio) continue;                       // fila incompleta: se ignora
  let desc = String(r['Descripcion'] || '').replace(/⭐/g, '').trim();
  if (/^-?\s*$/.test(desc)) desc = '';
  items.push({
    nombre,
    cantidad,
    unidad: unidadCorta(pres[2]),
    precio,
    precio_unidad: num(r['Precio Unitario ($)']) || Math.round(precio / cantidad),
    descripcion: desc
  });
}

const productos = {}, combos = [];
for (const it of items) {
  if (/^combo/i.test(it.nombre)) combos.push(it);
  else (productos[it.nombre] = productos[it.nombre] || []).push(it);
}

const lineas = Object.entries(productos).map(([nombre, pres]) => {
  pres.sort((a, b) => a.cantidad - b.cantidad);
  const desde = Math.min(...pres.map(p => p.precio_unidad));
  return `${nombre} (desde ${pesos(desde)}/${pres[0].unidad}): ` +
    pres.map(p => `${p.cantidad}${p.unidad} ${pesos(p.precio)}`).join(' | ');
});

const lineasCombos = combos.sort((a, b) => a.precio - b.precio).map(c => {
  const contenido = (c.descripcion.split(':').slice(1).join(':') || c.descripcion)
    .replace(/[!¡]/g, '').replace(/\s+/g, ' ').trim();
  return `${c.nombre} (${c.cantidad}${c.unidad}, 15 días) ${pesos(c.precio)}: ${contenido}`;
});

return [{ json: {
  catalogo_compacto: [
    'PRODUCTOS (nombre (desde precio/lb): presentación precio | ...):',
    ...lineas,
    '',
    'COMBOS:',
    ...lineasCombos
  ].join('\n'),
  catalogo_json: items,
  imagenes,
  productos_con_foto: Object.keys(imagenes).length,
  combo_mas_barato: combos.length ? pesos(Math.min(...combos.map(c => c.precio))) : null,
  total_filas: rows.length,
  filas_usadas: items.length
} }];

// Junta lo que necesitan el router y los agentes, todo desde el CRM:
//  - mensaje_para_ia: los mensajes nuevos del cliente (el buffer del CRM ya los unió)
//  - historial: la conversación anterior (incluye lo que respondió un asesor humano desde el CRM)
//  - contacto: etapa, etiquetas y campos personalizados
const cfg = $('CONFIG').first().json;
const claim = $('Reclamar mensajes').first().json;
const ctx = $('Contexto del contacto').first().json.data ?? {};
const msgs = $('Historial').first().json.data?.messages ?? [];

const mensaje = String(claim.text || cfg.content || '').trim().slice(0, 4000);

// El historial termina con los mensajes nuevos del cliente: se quitan para no duplicarlos
let hist = msgs.filter(m => m.from !== 'nota' && String(m.text || '').trim());
let pendientes = claim.count || 0;
while (pendientes > 0 && hist.length && hist[hist.length - 1].from === 'cliente') { hist.pop(); pendientes--; }

const QUIEN = { cliente: 'Cliente', ia: 'Asesora', agente: 'Asesora (persona del equipo)' };
const lineas = hist.slice(-20).map(m => `${QUIEN[m.from] || m.from}: ${String(m.text).replace(/\s+/g, ' ').slice(0, 300)}`);

const c = ctx.contact ?? {};
return [{ json: {
  mensaje_para_ia: mensaje,
  chatid: cfg.wa_id,
  historial: lineas,
  historial_texto: lineas.join('\n') || '(es el primer mensaje de esta conversación)',
  contacto: {
    nombre: c.nombre || cfg.contact_name || '',
    email: c.email || '',
    etapa: c.stage || 'Nuevo',
    etiquetas: c.tags ?? [],
    campos: c.custom_fields ?? {},
  },
} }];

// ============================================================
// NODO: Armar router Jev (decide qué agente responde)
// Jev recibe el último mensaje de la Asesora y el del cliente por separado,
// más el historial reciente del CRM como contexto, y responde UNA sola pregunta.
// ============================================================
const msg = $('Mensaje para la ia').first().json;
const mensajeNuevo = String(msg.mensaje_para_ia || '').trim().slice(0, 2000);
const lineas = msg.historial || [];

// Último mensaje de la Asesora (lo que el cliente está respondiendo)
let ultimaAsesora = '';
for (let i = lineas.length - 1; i >= 0; i--) {
  if (lineas[i].startsWith('Asesora')) { ultimaAsesora = lineas[i].replace(/^Asesora[^:]*:\s*/, ''); break; }
}

const esEmbajador = (msg.contacto.etiquetas || []).includes('Embajador');

const questions = {
  carril: {
    type: 'choice',
    instructions:
      'Which area of AgroApoya2 should answer `mensaje_nuevo`? ' +
      'First read `ultimo_mensaje_asesora`: when `mensaje_nuevo` is a short reply (yes, no, ok, thanks, please, "sí señora"), ' +
      'it continues the same topic as `ultimo_mensaje_asesora`. Use `historial` only as extra context. ' +
      'Choose a faq option or saludo only when the Cliente explicitly writes that; otherwise choose ventas.',
    criteria: {
      ventas:
        'Default. Buying groceries: products, prices, offers, combos, availability, coverage, delivery address, placing or completing an order, ' +
        'or any reply to an `ultimo_mensaje_asesora` about groceries or offers, including short replies such as "sí", "ok", "gracias", "por favor", ' +
        'and accepting to be notified when a new offer comes out.',
      embajadores:
        'The ambassador (embajador) program: the Cliente asks about being an ambassador, their referral link, commissions, payments or how to claim them, ' +
        'the ambassador WhatsApp group, how to share the offer or sell more to their neighbors, or replies to an `ultimo_mensaje_asesora` about the ambassador program. ' +
        'If `es_embajador` is true, questions about the current offer TO SHARE with neighbors (what is on offer this week, until when, which areas) also go here; ' +
        'only an ambassador buying groceries for their own home goes to ventas.',
      posventa:
        'An order the Cliente ALREADY placed: its status, delivery, a change or cancellation, a complaint about products or service already received, ' +
        'asking to talk to a human person, or a reply to an `ultimo_mensaje_asesora` about an existing order.',
      faq_fechas:
        'The Cliente explicitly asks when the delivery will be, until when they can order, or about schedules or hours. A short reply is never this option.',
      faq_metodo_pago:
        'The Cliente explicitly asks how to pay or which payment methods are accepted. A short reply is never this option.',
      faq_punto_fisico:
        'The Cliente explicitly asks where the store or physical location is, or where the products come from. A short reply is never this option.',
      faq_minimo_pedidos:
        'The Cliente explicitly asks what the minimum number of orders is or how that minimum works. A short reply is never this option.',
      saludo:
        '`mensaje_nuevo` is ONLY a greeting ("hola", "buenos días", "buenas tardes") or ONLY a generic request for information ' +
        '("quiero más información", "info") with no specific topic. If it also mentions any topic or answers the Asesora, choose that topic instead.'
    }
  }
};

return [{ json: { jev_body: {
  model: 'jev-latest',
  state: {
    negocio: 'AgroApoya2 sells fresh farm produce with home delivery in Bogotá and runs an ambassador (embajador) referral program. ' +
             'The chat is in Spanish on WhatsApp. Cliente is the customer; Asesora is the AgroApoya2 assistant.' +
             (esEmbajador ? ' This Cliente is already a registered ambassador.' : ''),
    es_embajador: esEmbajador,
    historial: lineas.slice(-20),
    ultimo_mensaje_asesora: ultimaAsesora.slice(0, 1200) || '(no previous message: this is the first contact)',
    mensaje_nuevo: mensajeNuevo
  },
  questions
} } }];

// ============================================================
// NODO: Decidir ruta (un solo dato de Jev: el carril)
// Salidas de "ruta": ventas | embajadores | posventa | plantilla
// El estado (carril, localidad) ahora vive en el CRM como campos personalizados.
// Regla general: ante la duda, responde el Agente Ventas.
// ============================================================
const jev    = $input.first().json;
const oferta = $('Get row(s) in sheet').first().json;
const m      = $('Mensaje para la ia').first().json;
const cfg    = $('CONFIG').first().json;
const coberturaTxt = String(oferta['Localidades'] || '');

// ---- Estado anterior, leído del CRM
const campos = m.contacto.campos || {};
const estado = { carril: campos.carril || null, localidad: campos.localidad_entrega || null };

const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();
const c = (jev && jev.answers && jev.answers.carril) || null;
const eleccion = c ? c.choice : null;
const conf = c ? (c.confidence || 0) : 0;

// ---- Umbrales: plantillas y carriles especiales solo con buena seguridad
const CONF_PLANTILLA = 0.75;   // saludo y preguntas frecuentes
const CONF_ESPECIAL  = 0.60;   // embajadores y posventa

// ---- Seguros con código (por si Jev se equivoca en lo obvio)
const texto = norm(m.mensaje_para_ia);
const RESPUESTA_CORTA = /^(si+|s[ií] se[nñ]ora|si sra|no|ok|okey|dale|listo|bueno|claro|gracias|muchas gracias|por favor|perfecto|de una|vale|y?a bueno)[\s.!,]*$/i;
const es_respuesta_corta = RESPUESTA_CORTA.test(texto) || texto.split(/\s+/).filter(Boolean).length <= 2 && !/\?/.test(texto);
const tiene_saludo = /\b(hola|buen[oa]s?|saludos|info|informacion|mas informacion)\b/.test(texto);

// ---- Decisión
const FAQ = { faq_fechas: 'fechas', faq_metodo_pago: 'metodo_pago', faq_punto_fisico: 'punto_fisico', faq_minimo_pedidos: 'minimo_pedidos' };
let ruta, plantilla = null;

if (!c) {
  ruta = estado.carril || 'ventas';                                 // Jev no respondió
} else if (FAQ[eleccion] && conf >= CONF_PLANTILLA && !es_respuesta_corta) {
  ruta = 'plantilla'; plantilla = FAQ[eleccion];
} else if (eleccion === 'saludo' && conf >= CONF_PLANTILLA && tiene_saludo) {
  ruta = 'plantilla'; plantilla = 'bienvenida';
} else if (['embajadores', 'posventa'].includes(eleccion) && conf >= CONF_ESPECIAL) {
  ruta = eleccion;
} else {
  ruta = 'ventas';                                                  // todo lo demás
}

// El carril guardado solo cambia cuando responde un agente
const carril = ['ventas', 'embajadores', 'posventa'].includes(ruta) ? ruta : estado.carril;

// ---- Localidad y cobertura (la guarda el agente en el CRM con set_fields localidad_entrega)
const localidad = estado.localidad;
const coberturas = coberturaTxt.split(/[-,;/]/).map(norm).filter(Boolean);
const cobertura_ok = localidad ? coberturas.includes(norm(localidad)) : null;

// ---- ¿La oferta sigue abierta? ("28 de Septiembre" -> se cierra 11:59 p. m. hora Bogotá)
const MESES = { enero:0,febrero:1,marzo:2,abril:3,mayo:4,junio:5,julio:6,agosto:7,septiembre:8,setiembre:8,octubre:9,noviembre:10,diciembre:11 };
function cierreOferta(txt) {
  const mm = norm(txt).match(/(\d{1,2})\s*de\s*([a-z]+)/);
  if (!mm || MESES[mm[2]] === undefined) return null;
  const hoy = new Date();
  const cierre = new Date(Date.UTC(hoy.getUTCFullYear(), MESES[mm[2]], Number(mm[1]), 23 + 5, 59));
  if (cierre - hoy < -180 * 864e5) cierre.setUTCFullYear(hoy.getUTCFullYear() + 1);
  return cierre;
}
const cierre = cierreOferta(oferta['Fecha Finalización ']);
const oferta_abierta = cierre ? new Date() <= cierre : true;

// ---- Contexto mínimo para los agentes
const whatsapp = String(cfg.wa_id || '').slice(-10);
const k = m.contacto;
const contexto_estado = [
  `nombre: ${k.nombre || 'desconocido'}`,
  `celular_whatsapp: ${whatsapp || 'desconocido'}`,
  `correo: ${k.email || 'no lo ha dado'}`,
  `etapa_crm: ${k.etapa}`,
  `etiquetas: ${(k.etiquetas || []).join(', ') || 'ninguna'}`,
  `es_embajador: ${(k.etiquetas || []).includes('Embajador') ? 'SÍ' : 'NO'}`,
  `carril: ${carril || 'nuevo'}`,
  `localidad: ${localidad || 'no la ha dicho'}`,
  `direccion_guardada: ${campos.direccion_entrega || 'no la ha dado'}`,
  `primera_compra: ${campos.primera_compra || 'no se sabe'}`,
  `cobertura_esta_semana: ${cobertura_ok === null ? 'sin verificar' : (cobertura_ok ? 'SÍ' : 'NO')}`,
  `oferta_abierta: ${oferta_abierta ? 'SÍ' : 'NO (ya cerró)'}`
].join(' | ');

return [{ json: {
  ruta, plantilla, carril, carril_anterior: estado.carril, localidad, cobertura_ok, oferta_abierta, contexto_estado,
  jev_ok: !!c, jev_eleccion: eleccion, jev_confianza: conf, jev_probabilidades: c ? c.probabilities : null
} }];

// ============================================================
// NODO: Respuesta de plantilla (0 tokens de LLM)
// Responde saludos ambiguos y preguntas frecuentes sin llamar a ningún agente.
// ============================================================
const d = $('Decidir ruta').first().json;
const oferta = $('Get row(s) in sheet').first().json;
const fechaCierre  = oferta['Fecha Finalización '];
const fechaEntrega = oferta['Fechas de entrega'];
const minimo       = oferta['No minimo Entregas'];

const hora = Number(new Date().toLocaleString('en-US', { timeZone: 'America/Bogota', hour: 'numeric', hour12: false }));
const saludo = hora < 12 ? 'Buenos días' : (hora < 19 ? 'Buenas tardes' : 'Buenas noches');

const T = {
  bienvenida: `¡${saludo}, sumercé! 🌱 Soy Lina de AgroApoya2. ¿Le ayudo con un pedido de mercado fresco del campo, o quiere conocer el Programa de Embajadores?`,
  fechas: d.oferta_abierta
    ? `La oferta de esta semana está abierta hasta el ${fechaCierre} y las entregas son el ${fechaEntrega}, sumercé. ¿Le armo su pedido?`
    : `La oferta de esta semana ya cerró, sumercé. En los próximos días sale la nueva cosecha. ¿Quiere que le avise apenas esté?`,
  punto_fisico: `No tenemos local en Bogotá, sumercé 🌱 Traemos todo directo del campo boyacense y se lo llevamos fresquito hasta su casa. ¿Le cuento qué hay esta semana?`,
  minimo_pedidos: `Como traemos todo directo del campo, despachamos cada zona cuando se juntan ${minimo} pedidos. Si esta semana no se completa, la entrega se corre un poquito y yo le aviso. Así le garantizamos producto fresco y a precio justo.`,
  metodo_pago: `El pago es contraentrega, sumercé: paga cuando recibe su mercado en la puerta de su casa. ¿Le armo el pedido?`,
  fuera_de_tema: `Sumercé, por este chat le ayudo con pedidos de mercado fresco y con el Programa de Embajadores de AgroApoya2. ¿Le interesa alguno de los dos?`
};

return [{ json: { respuesta: T[d.plantilla] || T.bienvenida } }];

// ============================================================
// NODO: Post-proceso (después de CUALQUIER agente o plantilla)
// Limpia lo que WhatsApp no renderiza, hace cumplir las reglas de forma
// y saca las fotos pedidas con [IMAGEN: producto].
// ============================================================
let t = String($input.first().json.output || $input.first().json.respuesta || '');
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim();

// Fotos: [IMAGEN: Papa pastusa] -> se envían aparte si el producto tiene foto en la hoja
const pedidas = [];
t = t.replace(/\[IMAGEN:\s*([^\]]+)\]/gi, (_, n) => { pedidas.push(n.trim()); return ''; });
const fotos = $('Catálogo compacto').first().json.imagenes || {};
const imagenes = [...new Set(pedidas)].slice(0, 3)
  .map(n => ({ producto: n, url: fotos[norm(n)] || Object.entries(fotos).find(([k]) => k.includes(norm(n)) || norm(n).includes(k))?.[1] }))
  .filter(i => i.url);

t = t.replace(/\*\*(.+?)\*\*/g, '*$1*')          // **negrita** -> *negrita* (formato WhatsApp)
     .replace(/^#{1,6}\s*/gm, '')                // títulos markdown
     .replace(/^\s*[-•]\s+(?=\S)/gm, '')         // viñetas al inicio de línea
     .replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '$1: $2') // [texto](link) -> texto: link
     .replace(/\n{3,}/g, '\n\n')
     .trim();

// Máximo 1 emoji: se conserva el primero
const EMOJI = /\p{Extended_Pictographic}️?/gu;
let visto = false;
t = t.replace(EMOJI, e => (visto ? '' : (visto = true, e))).replace(/[ \t]{2,}/g, ' ').replace(/[ \t]+\n/g, '\n').trim();

return [{ json: { respuesta: t, largo: t.length, imagenes } }];

// ============================================================
// NODO: Armar Jev CRM (clasifica la conversación para mover etapa y etiquetas)
// Corre DESPUÉS de responder: no demora la respuesta al cliente.
// Para agregar otra decisión, agrega una pregunta aquí y su regla en "Acciones para el CRM".
// ============================================================
const m = $('Mensaje para la ia').first().json;
const d = $('Decidir ruta').first().json;
const respuesta = $('Post-proceso').first().json.respuesta;

const questions = {
  etapa: {
    type: 'choice',
    instructions: 'Given the whole conversation, including `respuesta_asesora` (the reply just sent), which sales stage is this Cliente in right now?',
    criteria: {
      contactado: 'The Cliente only greeted, asked something general, or has not shown interest in buying or in the ambassador program yet.',
      interesado: 'The Cliente asked for prices, products, combos or coverage, gave their localidad, or showed interest in buying or in becoming an ambassador.',
      negociacion: 'The Cliente is building a cart, chose products and quantities, is giving delivery data (name, address, email) or is confirming the order summary.',
      ganado: 'In this conversation the order was confirmed by the Cliente and registered by the Asesora ("su pedido quedó registrado"), or the Cliente was registered as an ambassador.',
      perdido: 'The Cliente clearly said they do not want to buy, asked not to be contacted, or is out of coverage and not interested in being notified.'
    }
  },
  interes: {
    type: 'choice',
    instructions: 'What is the main topic of the Cliente in the latest messages?',
    criteria: {
      ninguno: 'Greeting, thanks or nothing specific.',
      compra: 'Buying groceries from the current offer.',
      embajador: 'Becoming an ambassador or the ambassador program.',
      posventa: 'An order already placed: status, change, cancellation or delivery.',
      queja: 'A complaint about a product, a delivery or the service.',
      fuera_cobertura: 'The Asesora said the Cliente\'s localidad has no coverage this week.'
    }
  }
};

return [{ json: { jev_body: {
  model: 'jev-latest',
  state: {
    negocio: 'AgroApoya2 sells fresh farm produce with home delivery in Bogotá and runs an ambassador referral program. Chat in Spanish on WhatsApp.',
    etapa_actual: m.contacto.etapa,
    carril: d.carril,
    historial: (m.historial || []).slice(-16),
    mensaje_cliente: m.mensaje_para_ia,
    respuesta_asesora: respuesta
  },
  questions
} } }];

// ============================================================
// NODO: Acciones para el CRM (reglas en código sobre lo que decidió Jev)
// Cada item que sale es una llamada a /api/bot/<tool>. Todas quedan en
// CRM → Configuración → Agente IA → Acciones de la IA, y en la ficha del contacto.
// ============================================================
const a = $input.first().json?.answers || {};
const m = $('Mensaje para la ia').first().json;
const cfg = $('CONFIG').first().json;
const base = { tenant_id: cfg.config.tenant_id, wa_id: cfg.wa_id };
const out = [];

// ---- Etapa del embudo: solo avanza (nunca retrocede) y con buena seguridad
const ORDEN = ['Nuevo', 'Contactado', 'Interesado', 'Negociación', 'Cerrado ganado', 'Cerrado perdido'];
const ETAPA = { contactado: 'Contactado', interesado: 'Interesado', negociacion: 'Negociación', ganado: 'Cerrado ganado', perdido: 'Cerrado perdido' };
const MIN_CONF = { 'Cerrado ganado': 0.85, 'Cerrado perdido': 0.85 };
const actual = ORDEN.includes(m.contacto.etapa) ? m.contacto.etapa : 'Nuevo';
const cerrada = actual.startsWith('Cerrado');
const e = a.etapa;
let nueva = null;
if (e && ETAPA[e.choice] && !cerrada) {
  const cand = ETAPA[e.choice];
  if (ORDEN.indexOf(cand) > ORDEN.indexOf(actual) && (e.confidence || 0) >= (MIN_CONF[cand] ?? 0.7)) nueva = cand;
}
if (!nueva && actual === 'Nuevo') nueva = 'Contactado';            // ya le respondimos
if (nueva) out.push({ tool: 'set_stage', body: { ...base, stage: nueva,
  reason: e ? `Jev: ${e.choice} (${Math.round((e.confidence || 0) * 100)}%)` : 'Primera respuesta del bot' } });

// ---- Etiquetas por tema
const TAG = { compra: 'Interesado oferta', embajador: 'Quiere ser embajador', posventa: 'Posventa', queja: 'Queja', fuera_cobertura: 'Fuera de cobertura' };
const i = a.interes;
const tag = i && TAG[i.choice];
